n30083.content:
\begin{theorem} \label{thm:BombierSchmidtforThueEqs}
  \uses{def:omega}
  Given integers $n,a_1,a_2\neq0$ and $p\ge3$, there are
  at most $O(p^{1+\omega(|n|)})$ many solutions
  $(x_1,x_2)\in\mathbb{Z}^2$ such that $|x_i|\le X_i$ and
  \begin{align*}
    n = a_1 x_1^p + a_2 x_2^p.
  \end{align*}
\end{theorem}

n30085.content:
\begin{definition}\label{def:omega}
Let $\omega(n)$ denote the number of distinct prime factors of an integer $n$.
\end{definition}

n30089.content:
\begin{proof}
  \proves{lem:MixedDetMethods}
  \uses{lem:EisensteinCrit,thm:BombieriPilaforDet,thm:HeathBrownpadicDet}
  We fix a choice of non-zero integer $z\in [-Z,Z]$, of which there are $O(Z)$. When $z$ is fixed, the resulting equation defines a curve in $\mathbb{A}^2$ and we can hope to apply work of Bombieri-Pila~\cite[Theorem~4]{bp}, which would show that the equation has $O_{\varepsilon,D}(\max(X,Y)^{\frac{1}{\max(p,q)}+\varepsilon})$ integer solutions in the region $|x|\leq X$ and $|y|\leq Y$, where the implied constant only depends on $\varepsilon$ and $D$. This is valid only when
  the curve is absolutely irreducible, which we claim is true when $z\neq 0$. But, for fixed $z\in \mathbb{Z}_{\neq 0}$ the
  polynomial $a_2y^q+a_3z^r$ has non-zero discriminant as a polynomial in $y$. Hence the claim follows from Lemma~\ref{eis}. Rather than appealing to Bombieri-Pila, however, we can get a sharper bound by using work of
  Heath-Brown~\cite[Theorem 15]{cime}. For fixed $z\in \mathbb{Z}_{\neq 0}$ this gives the bound
  $O_{\varepsilon,D}(\min(X^{\frac{1}{q}},Y^{\frac{1}{p}})(XY)^\varepsilon)$ for the number of available $x,y$.
\end{proof}

n30091.content:
\begin{proof}
  \uses{thm:QuadraticFormsEstimate,thm:BombierSchmidtforThueEqs,lem:omegaUpperBound}
  Suppose now that $p=q\geq 2$. Then, for given $z\in \mathbb{Z}_{\neq 0}$, we are left with counting the number of integer solutions to the equation $N=a_1x^p+a_2y^p$, with $|x|,|y|\leq \max(X,Y)$, and
  where $N=-a_3z^r$. For $p=2$ this is a classical problem in quadratic forms. The
  bound $O_{\varepsilon,D}((|a_1a_2N|XY)^\varepsilon)$ follows from Heath-Brown~\cite[Theorem~3]{cubic}, for example.
  For $p\geq 3$ we obtain a Thue equation. According to work of Bombieri and Schmidt~\cite{bs}, there are at most $O(p^{1+\omega(|N|)})$ solutions, for an absolute implied constant. Using the bound $\omega(|N|)\ll \log(3|N|)/(\log \log(3|N|))$, this is $O_{\varepsilon,D}((|a_3|Z)^\varepsilon)$, which thereby completes the proof of the lemma.
\end{proof}

