  \delta_{ab}, \delta_{ac}, \delta_{bc} \leq 0.00\overline{6} + \varepsilon^2,
  \end{equation}
  \begin{equation}\label{eq:robin1}
  -0.00\bar 6 - \delta \leq \delta_a,\delta_b,\delta_c \leq 0.01\bar3+\delta+\varepsilon,
  \end{equation}
  and
  \begin{equation}\label{eq:robin3}
